import{_ as a,o,c as t,a5 as r}from"./chunks/framework.BiZGiucB.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"en/vue2/guide/faq.md","filePath":"en/vue2/guide/faq.md","lastUpdated":1791538191000}'),s={name:"en/vue2/guide/faq.md"};function n(i,e,d,l,h,c){return o(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="why-does-a-native-fullscreen-request-fail" tabindex="-1">Why does a native fullscreen request fail? <a class="header-anchor" href="#why-does-a-native-fullscreen-request-fail" aria-label="Permalink to &quot;Why does a native fullscreen request fail?&quot;">​</a></h2><p>Check the error event or rejected Promise. The browser requires a direct user gesture; requests made after a network call, timer or automatic mount can be rejected. An iframe also needs permission from its host to use fullscreen.</p><p><code>isEnabled</code> only indicates API support. Try <code>pageOnly</code> to distinguish native permission issues from other problems.</p><h2 id="why-does-fullscreen-behave-differently-on-mobile" tabindex="-1">Why does fullscreen behave differently on mobile? <a class="header-anchor" href="#why-does-fullscreen-behave-differently-on-mobile" aria-label="Permalink to &quot;Why does fullscreen behave differently on mobile?&quot;">​</a></h2><p>Native fullscreen support varies by browser, device and embedding context. The library uses page-only mode when native fullscreen is unavailable. Page-only mode keeps browser controls visible. Check the behavior on the target device.</p><h2 id="why-are-dropdowns-or-dialogs-hidden" tabindex="-1">Why are dropdowns or dialogs hidden? <a class="header-anchor" href="#why-are-dropdowns-or-dialogs-hidden" aria-label="Permalink to &quot;Why are dropdowns or dialogs hidden?&quot;">​</a></h2><p>Try <code>teleport</code>, which makes the body the native fullscreen target. The UI library still controls where overlays are mounted and how they are stacked. For page-only mode, set background, <code>z-index</code> and overflow styles on <code>fullscreenClass</code> as needed.</p><h2 id="why-do-styles-change-with-teleport" tabindex="-1">Why do styles change with teleport? <a class="header-anchor" href="#why-do-styles-change-with-teleport" aria-label="Permalink to &quot;Why do styles change with teleport?&quot;">​</a></h2><p>The target moves from its original parent to the body. Ancestor selectors and inherited values may no longer apply. Put important styles directly on the target. On exit, the original location and the inline layout properties changed by the library are restored.</p><h2 id="can-i-use-ssr-or-nuxt" tabindex="-1">Can I use SSR or Nuxt? <a class="header-anchor" href="#can-i-use-ssr-or-nuxt" aria-label="Permalink to &quot;Can I use SSR or Nuxt?&quot;">​</a></h2><p>The package can be imported on the server. Read DOM elements after mount and request native fullscreen from a browser user action. Do not call <code>api.request()</code> on the server.</p><h2 id="why-does-api-state-not-update-the-ui" tabindex="-1">Why does API state not update the UI? <a class="header-anchor" href="#why-does-api-state-not-update-the-ui" aria-label="Permalink to &quot;Why does API state not update the UI?&quot;">​</a></h2><p><code>api.isFullscreen</code> is not a reactive ref. Use <code>callback</code> to update Vue state, or use the component&#39;s <code>v-model</code>.</p><h2 id="how-should-i-handle-route-changes" tabindex="-1">How should I handle route changes? <a class="header-anchor" href="#how-should-i-handle-route-changes" aria-label="Permalink to &quot;How should I handle route changes?&quot;">​</a></h2><p>The component cleans up on unmount. When using the API or directive directly, await <code>api.exit()</code> before the route removes the target. Removing a directive only removes its click listener; it does not own the shared API session.</p>',16)])])}const f=a(s,[["render",n]]);export{p as __pageData,f as default};
